/// Binary-search lookup of a 16x16 CJK bitmap glyph in O(log N) time (~13 comparisons for 6,800 chars)
#[inline]
pub fn lookup_cjk(ch: char) -> Option<[u16; 16]> {
    let code = ch as u32;
    CJK_FONT_TABLE
        .binary_search_by_key(&code, |&(k, _)| k)
        .ok()
        .map(|idx| CJK_FONT_TABLE[idx].1)
}

#[inline]
pub fn lookup_cjk_16x16(ch: char) -> Option<[u16; 16]> {
    lookup_cjk(ch)
}

