#[inline]
pub fn lookup_aa_ascii(ch: char) -> Option<&'static [u8; 90]> {
    let c = ch as u32;
    if (0x20..=0x7E).contains(&c) {
        Some(&AA_ASCII_TABLE[(c - 0x20) as usize])
    } else {
        None
    }
}

#[inline]
pub fn lookup_aa_cjk(ch: char) -> Option<&'static [u8; 128]> {
    let code = ch as u32;
    AA_CJK_TABLE
        .binary_search_by_key(&code, |&(k, _)| k)
        .ok()
        .map(|idx| &AA_CJK_TABLE[idx].1)
}
